\indcase{!A}{\lexists[X][!B]}{$\Sat{M}{\indfrm}[s]$ iff for at least
  one $M \subseteq \Domain{M}^n$ so that
  $\Sat{M}{!B}[\Subst{s}{M}{X}]$.}

\indcase{!A}{\lexists[u][!B]}{$\Sat{M}{\indfrm}[s]$ iff for at least
  one $f\colon \Domain{M}^n \to \Domain{M}$ so that
  $\Sat{M}{!B}[\Subst{s}{f}{u}]$.}
